-- 1) NAMESPACE: bag of related functions
local Utils = {}
function Utils.shout(text) print(string.upper(text)) end
return Utils

-- 2) SINGLETON: shared state object
local Scoreboard = { scores = {} }
function Scoreboard.add(player, points)
    Scoreboard.scores[player.UserId] = (Scoreboard.scores[player.UserId] or 0) + points
end
return Scoreboard

-- 3) FACTORY: makes fresh objects
local Pet = {}
Pet.__index = Pet
function Pet.new(name)
    return setmetatable({ name = name, hunger = 100 }, Pet)
end
function Pet:feed(amount) self.hunger = math.min(100, self.hunger + amount) end
return Pet
